// Static tables generated by build.rs, one set per encoding, plus the lookups that read them: whole-token lookup
// by bytes and merge lookup by token pair. Lookups are generic over the vocabulary, so each encoding gets its own
// copy with its table addresses and sizes as constants.

use crate::table_hash::*;

/// Forces 64-byte alignment on embedded table images so they can be viewed as u32/u64 arrays.
#[repr(C, align(64))]
pub(crate) struct Aligned<T>(pub T);

/// One encoding's ordinary vocabulary, as tables generated by build.rs.
pub(crate) trait Vocabulary {
    /// Number of ordinary tokens.
    const TOKEN_COUNT: usize;
    /// Ordinary token ids are below this. It exceeds `TOKEN_COUNT` when some ids below it have no ordinary token
    /// (`p50k_base`'s 50256); those ids have empty bytes in the tables.
    const ORDINARY_ID_END: usize;
    const VOCAB_TABLE_BITS: u32;
    const PAIR_TABLE_BITS: u32;
    fn byte_tokens() -> &'static [u32; 256];
    fn token_offsets() -> &'static [u32];
    fn token_bytes() -> &'static [u8];
    fn vocab_table() -> &'static [u64];
    fn pair_table() -> &'static [u64];
    fn byte_pair_ranks() -> &'static [u32];
    fn premerged_char_tokens() -> &'static [u32];
    fn continuation_lead_ranks() -> &'static [u32];
}

/// Includes the tables build.rs generated for one encoding and implements `Vocabulary` for `$vocabulary`.
macro_rules! generated_vocabulary {
    ($(#[$attribute:meta])* $vocabulary:ident, $module:ident, $file:literal) => {
        $(#[$attribute])*
        mod $module {
            use super::Aligned;
            include!(concat!(env!("OUT_DIR"), "/", $file));
        }

        $(#[$attribute])*
        pub(crate) struct $vocabulary;

        $(#[$attribute])*
        impl Vocabulary for $vocabulary {
            const TOKEN_COUNT: usize = $module::TOKEN_COUNT;
            const ORDINARY_ID_END: usize = $module::ORDINARY_ID_END;
            const VOCAB_TABLE_BITS: u32 = $module::VOCAB_TABLE_BITS;
            const PAIR_TABLE_BITS: u32 = $module::PAIR_TABLE_BITS;
            #[inline(always)]
            fn byte_tokens() -> &'static [u32; 256] {
                &$module::BYTE_TOKENS
            }
            #[inline(always)]
            fn token_offsets() -> &'static [u32] {
                $module::TOKEN_OFFSETS
            }
            #[inline(always)]
            fn token_bytes() -> &'static [u8] {
                $module::TOKEN_BYTES
            }
            #[inline(always)]
            fn vocab_table() -> &'static [u64] {
                $module::VOCAB_TABLE
            }
            #[inline(always)]
            fn pair_table() -> &'static [u64] {
                $module::PAIR_TABLE
            }
            #[inline(always)]
            fn byte_pair_ranks() -> &'static [u32] {
                $module::BYTE_PAIR_RANKS
            }
            #[inline(always)]
            fn premerged_char_tokens() -> &'static [u32] {
                $module::PREMERGED_CHAR_TOKENS
            }
            #[inline(always)]
            fn continuation_lead_ranks() -> &'static [u32] {
                $module::CONTINUATION_LEAD_RANKS
            }
        }
    };
}

generated_vocabulary!(O200kBaseVocabulary, o200k_base_tables, "o200k_base_tables.rs");
generated_vocabulary!(
    #[cfg(feature = "cl100k_base")]
    Cl100kBaseVocabulary,
    cl100k_base_tables,
    "cl100k_base_tables.rs"
);
generated_vocabulary!(
    #[cfg(feature = "r50k_base")]
    R50kBaseVocabulary,
    r50k_base_tables,
    "r50k_base_tables.rs"
);
generated_vocabulary!(
    #[cfg(feature = "p50k_base")]
    P50kBaseVocabulary,
    p50k_base_tables,
    "p50k_base_tables.rs"
);

const PAIR_RANK_MASK: u64 = (1 << PAIR_ID_BITS) - 1;
/// Rank (merged token id) meaning "these two parts never merge".
pub(crate) const NO_MERGE: u32 = u32::MAX;

/// Bytes of an ordinary token, empty for ids without one. `id` must be below `V::ORDINARY_ID_END`.
#[inline]
pub(crate) fn ordinary_token_bytes<V: Vocabulary>(id: u32) -> &'static [u8] {
    let (id, offsets) = (id as usize, V::token_offsets());
    &V::token_bytes()[offsets[id] as usize..offsets[id + 1] as usize]
}

/// Little-endian value of up to 8 bytes, zero padded. Overlapping loads avoid a variable-length copy.
#[inline(always)]
fn load_le_padded(bytes: &[u8]) -> u64 {
    let len = bytes.len();
    if len >= 8 {
        u64::from_le_bytes(bytes[..8].try_into().unwrap())
    } else if len >= 4 {
        let low = u32::from_le_bytes(bytes[..4].try_into().unwrap()) as u64;
        let high = u32::from_le_bytes(bytes[len - 4..len].try_into().unwrap()) as u64;
        low | high << (8 * (len - 4))
    } else if len > 0 {
        bytes[0] as u64 | (bytes[len / 2] as u64) << (8 * (len / 2)) | (bytes[len - 1] as u64) << (8 * (len - 1))
    } else {
        0
    }
}

/// The ordinary token whose bytes are exactly `bytes`, if any.
#[inline]
pub(crate) fn token_id_for_bytes<V: Vocabulary>(bytes: &[u8]) -> Option<u32> {
    let len = bytes.len();
    // One- and two-byte pieces are most pieces in typical text; direct tables skip hashing.
    match len {
        1 => return Some(V::byte_tokens()[bytes[0] as usize]),
        2 => {
            let id = byte_merge_rank::<V>(bytes[0], bytes[1]);
            return (id != NO_MERGE).then_some(id);
        }
        0 => return None,
        _ if len > MAX_TOKEN_BYTES => return None,
        _ => {}
    }
    let head = load_le_padded(bytes);
    let tail = if len > 8 { load_le_padded(&bytes[8..len.min(INLINE_TOKEN_BYTES)]) as u32 } else { 0 };
    let expected = tail as u64 | (len as u64) << VOCAB_SLOT_LEN_SHIFT;
    let (table, slot_mask) = (V::vocab_table(), (1 << V::VOCAB_TABLE_BITS) - 1);
    let mut slot = vocab_slot_for(head, tail, len, V::VOCAB_TABLE_BITS);
    loop {
        let (slot_head, slot_info) = (table[2 * slot], table[2 * slot + 1]);
        if slot_info == 0 {
            return None;
        }
        if slot_head == head && slot_info & !VOCAB_SLOT_ID_MASK == expected {
            let id = ((slot_info & VOCAB_SLOT_ID_MASK) >> VOCAB_SLOT_ID_SHIFT) as u32;
            if len <= INLINE_TOKEN_BYTES || ordinary_token_bytes::<V>(id) == bytes {
                return Some(id);
            }
        }
        slot = (slot + 1) & slot_mask;
    }
}

/// Rank of merging two adjacent tokens: the merged token's id, or `NO_MERGE`.
#[inline(always)]
pub(crate) fn merge_rank<V: Vocabulary>(left: u32, right: u32) -> u32 {
    let key = pair_key(left, right);
    let (table, slot_mask) = (V::pair_table(), (1 << V::PAIR_TABLE_BITS) - 1);
    let mut slot = pair_slot_for(key, V::PAIR_TABLE_BITS);
    loop {
        let entry = table[slot];
        if entry >> PAIR_ID_BITS == key {
            return (entry & PAIR_RANK_MASK) as u32;
        }
        if entry == PAIR_EMPTY_SLOT {
            return NO_MERGE;
        }
        slot = (slot + 1) & slot_mask;
    }
}

/// Rank of merging two single-byte tokens.
#[inline(always)]
pub(crate) fn byte_merge_rank<V: Vocabulary>(left: u8, right: u8) -> u32 {
    V::byte_pair_ranks()[(left as usize) << 8 | right as usize]
}

/// Token of the 2- or 3-byte character starting at `piece[at]`, and its length, if merging may start with the
/// character as one part instead of separate bytes without changing the result (see `build.rs`).
#[inline(always)]
pub(crate) fn premerged_char<V: Vocabulary>(piece: &[u8], at: usize) -> Option<(u32, usize)> {
    let (len, lead_bits) = match piece[at] {
        lead @ 0xC2..=0xDF => (2, lead & 0x1F),
        lead @ 0xE0..=0xEF => (3, lead & 0x0F),
        _ => return None,
    };
    let continuation = piece.get(at + 1..at + len)?;
    let next = piece.get(at + len).copied();
    if !continuation.iter().all(|&byte| is_continuation_byte(byte))
        || (at > 0 && !is_continuation_byte(piece[at - 1]))
        || next.is_some_and(|byte| !starts_multibyte_sequence(byte))
    {
        return None;
    }
    let code_point =
        continuation.iter().fold(lead_bits as usize, |code_point, &byte| code_point << 6 | (byte & 0x3F) as usize);
    // Overlong 3-byte forms are not that code point's bytes. Surrogates have no character, so their entries are 0.
    if len == 3 && code_point < 0x800 {
        return None;
    }
    let id = V::premerged_char_tokens()[code_point];
    // A token joining the last byte to the next character must rank above the character's own token, its last
    // merge.
    let joins_next_first = next.is_some_and(|lead| {
        V::continuation_lead_ranks()[((code_point & 0x3F) << 6) | (lead & 0x3F) as usize] < id
    });
    (id != 0 && !joins_next_first).then_some((id, len))
}
